WITH base AS (SELECT id, shipped_date, delivered_date, status, LOWER(status) AS status_lower, COALESCE(carrier, 'NONE') AS carrier_clean FROM shipments WHERE delivered_date > DATE '2023-07-10' AND carrier IS NOT NULL), base_shipments AS (SELECT *, DATE_TRUNC('year', shipped_date) AS shipped_date_period, LAST_DAY(shipped_date) AS shipped_date_month_end FROM base WHERE shipped_date > TO_DATE('2023-07-03') AND delivered_date >= '2024-03-26'), flagged AS (SELECT *, CASE WHEN shipped_date_period - LAG(shipped_date_period) OVER (PARTITION BY status ORDER BY shipped_date_period, id) > INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM base_shipments), islands AS (SELECT id, status, status_lower, shipped_date_period, SUM(is_new_session) OVER (PARTITION BY status ORDER BY shipped_date_period, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged), scored AS (SELECT id, status, status_lower, shipped_date_period, island_id, AVG(island_id) OVER (PARTITION BY status ORDER BY shipped_date_period, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS island_id_avg_6_prior, COUNT(island_id) OVER (PARTITION BY status ORDER BY CAST(shipped_date_period AS BIGINT) RANGE BETWEEN 604800 PRECEDING AND CURRENT ROW) AS island_id_count_7d, NTILE(5) OVER w_hist AS island_id_bucket, AVG(island_id) OVER (PARTITION BY status) AS status_avg_island_id, SUM(island_id) OVER w_running AS cumulative_island_id FROM islands WHERE HOUR(shipped_date_period) BETWEEN 6 AND 9 WINDOW w_hist AS (ORDER BY island_id, id), w_running AS (PARTITION BY status ORDER BY island_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), scored_shipments AS (SELECT id, status, status_lower, island_id_count_7d, SUM(island_id_bucket) OVER (PARTITION BY status) AS status_sum_island_id_bucket, LAG(island_id_bucket, 1) OVER (PARTITION BY status ORDER BY island_id_bucket, id) AS prev_island_id_bucket FROM scored), metrics AS (SELECT id, status, status_sum_island_id_bucket, SUM(prev_island_id_bucket) OVER (PARTITION BY status ORDER BY status_sum_island_id_bucket, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_prev_island_id_bucket, ROW_NUMBER() OVER (ORDER BY island_id_count_7d, id) AS event_seq FROM scored_shipments), grouped AS (SELECT CASE WHEN cumulative_prev_island_id_bucket >= 39 THEN 'HIGH' ELSE 'LOW' END AS cumulative_prev_island_id_bucket_tier, status, PERCENTILE_APPROX(status_sum_island_id_bucket, ARRAY(0.25, 0.5, 0.75)) AS status_sum_island_id_bucket_quartiles, APPROX_PERCENTILE(status_sum_island_id_bucket, ARRAY(0.25, 0.5, 0.75)) AS status_sum_island_id_bucket_quartiles_2, PERCENTILE_APPROX(event_seq, 0.9) AS event_seq_p90, COUNT(*) FILTER (WHERE status = 'DELIVERED') AS delivered_rows, COUNT(*) FILTER (WHERE status = 'RETURNED') AS returned_rows, SIZE(COLLECT_SET(status)) AS num_status, DENSE_RANK() OVER (PARTITION BY CASE WHEN cumulative_prev_island_id_bucket >= 39 THEN 'HIGH' ELSE 'LOW' END ORDER BY PERCENTILE_APPROX(event_seq, 0.9) DESC) AS event_seq_p90_dense_rank FROM metrics GROUP BY CASE WHEN cumulative_prev_island_id_bucket >= 39 THEN 'HIGH' ELSE 'LOW' END, status) SELECT cumulative_prev_island_id_bucket_tier, status, status_sum_island_id_bucket_quartiles, status_sum_island_id_bucket_quartiles_2, event_seq_p90, delivered_rows, num_status, event_seq_p90_dense_rank, CASE WHEN status RLIKE '^(IN_TRANSIT|RETURNED)$' THEN 'GROUP_B' ELSE 'OTHER_ZONE' END AS status_zone FROM grouped
